type Page = 'overview' | 'strategies' | 'homework' | 'anya' | 'prompts' | 'textbook' | 'accounts' | 'migration'
const KnowledgePage = lazy(() => import('./KnowledgePage'))
type Modal = 'group' | 'student' | 'task' | 'taskDetail' | 'backup' | null
type ConfirmState = { title:string; description:string; confirmLabel:string; danger?:boolean; action:()=>void|Promise<void>; getErrorMessage?:(error:unknown)=>string }
const nav: { id: Page; label: string; icon: typeof LayoutDashboard }[] = [
  { id: 'overview', label: 'Обзор', icon: LayoutDashboard }, { id: 'strategies', label: 'Стратегии', icon: Users },
  { id: 'homework', label: 'Домашние задания', icon: ClipboardList }, { id: 'anya', label: 'Задачи Ани', icon: Sparkles },
  { id: 'prompts', label: 'Промпты', icon: FileText }, { id: 'textbook', label: 'Учебник', icon: BookOpen },
]
const ownerNav = [
  { id: 'accounts' as const, label: 'Аккаунты', icon: IdentificationBadge },
  { id: 'migration' as const, label: 'Миграция', icon: Database },
]
const blankLinks = { figma: '', portfolio: '', resume: '', telegram: '', notion: '' }
const newGroup = (): Group => ({ id: uid(), name: '', startsAt: today(), endsAt: '', actualEndsAt: '', status: 'backlog', statusBeforeArchive: null, notes: '', createdAt: new Date().toISOString() })
const newStudent = (groupId: string): Student => ({ id: uid(), groupId, name: '', age: null, photo: '', avatarIndex: -1, stage: 'start', startsAt: today(), level: '', desiredPosition: '', careerGoal: '', links: { ...blankLinks }, background: '', experience: '', strengths: '', growthAreas: '', difficulties: '', expectations: '', personalNotes: '', pointA: '', pointB: '', notes: '', strategyUpdatedAt: new Date().toISOString(), createdAt: new Date().toISOString() })
const newTask = (studentId: string, order: number, stage: Stage): StrategyTask => ({ id: uid(), studentId, title: '', description: '', stage, status: 'backlog', studyStatus:'not_started', sectionId:'', period:'', materials:[], owner: 'Не назначен', dueAt: '', url: '', comments: '', order, blocker: false, createdAt: new Date().toISOString(), updatedAt: new Date().toISOString(), reviewStatus:'none', approvalStatus:null, approvalType:'', approvalSentAt:'', approvalComment:'', history:[] })
const learningUiError=(error:unknown)=>Object.assign(new Error(learningErrorMessage(error)),{cause:error})

function App() {
  const calm = useCalmMotion()
  const currentUser = useCurrentUser()
  const { logout, refreshCurrentUser } = useAuth()
  const [serverCutover, setServerCutover] = useState(hasServerCutover)
  const [data, setLegacyDataState] = useState<AppData>(loadData)
  const setData: Dispatch<SetStateAction<AppData>> = useCallback(next => {
    if (hasServerCutover()) { setServerCutover(true); return }
    setLegacyDataState(next)
  }, [])
  const [page, setPage] = useState<Page>('overview')
  const [groupsView,setGroupsView]=useState<'groups'|'students'>('groups')
  const [groupsFilter,setGroupsFilter]=useState<GroupStatus>('active')
  const [groupId, setGroupId] = useState<string | null>(null)
  const [studentId, setStudentId] = useState<string | null>(null)
  const [modal, setModal] = useState<Modal>(null)
  const [draftGroup, setDraftGroup] = useState<Group | null>(null)
  const [draftStudent, setDraftStudent] = useState<Student | null>(null)
  const [draftTask, setDraftTask] = useState<StrategyTask | null>(null)
  const [focusedTaskId, setFocusedTaskId] = useState<string | null>(null)
  const [focusedHomeworkId, setFocusedHomeworkId] = useState<string | null>(null)
  const [profileTab, setProfileTab] = useState<ProfileTab>('overview')
  const [returnPage,setReturnPage]=useState<Page|null>(null)
  const [studentBackToRoster,setStudentBackToRoster]=useState(false)
  const [recordSource,setRecordSource]=useState<RecordSource>('server')
  const [formSource,setFormSource]=useState<RecordSource>('server')
  const [profileNavigationKey,setProfileNavigationKey]=useState(0)
      const [searchOpen, setSearchOpen] = useState(false)
  const [searchTerm, setSearchTerm] = useState('')
  const [saveError, setSaveError] = useState(false)
  const [confirmState,setConfirmState] = useState<ConfirmState|null>(null)
  const [notice,setNotice] = useState<{title:string;description:string}|null>(null)
  const [logoutPending,setLogoutPending] = useState(false)
  const [formPending,setFormPending]=useState(false)
  const formPendingRef=useRef(false)
  const [formError,setFormError]=useState('')
  const skipInitialLegacySave = useRef(true)
  const dataRef = useRef(data)
  dataRef.current = data
  const visibleNav = useMemo(() => currentUser.is_owner ? [...nav, ...ownerNav] : nav, [currentUser.is_owner])
  const serverDomain = useServerGroupsStudents(currentUser.id)
  const strategyDomain = useServerStrategies(currentUser.id,serverDomain.students)
  const learningDomain = useServerLearning(currentUser.id,serverDomain.students,strategyDomain.strategies,strategyDomain.refreshStudent)
  const domainData = useMemo<AppData>(() => withServerLearning(withServerStrategies(serverDomainData(data,serverDomain.groups,serverDomain.students),strategyDomain.sections,strategyDomain.tasks),learningDomain.meetings,learningDomain.homeworks), [data, serverDomain.groups, serverDomain.students, strategyDomain.sections, strategyDomain.tasks, learningDomain.meetings, learningDomain.homeworks])

  useEffect(() => {
    if (skipInitialLegacySave.current) { skipInitialLegacySave.current = false; return }
    if (serverCutover) return
    try { localStorage.setItem(STORAGE_KEY, JSON.stringify(data)); setSaveError(false) } catch { setSaveError(true) }
  }, [data, serverCutover])
  useEffect(() => {
    const syncCutover = (event: StorageEvent) => { if (event.key === SERVER_CUTOVER_KEY && event.newValue === 'complete') setServerCutover(true) }
    window.addEventListener('storage', syncCutover)
    return () => window.removeEventListener('storage', syncCutover)
  }, [])
  useEffect(() => {
    if (!serverCutover || recordSource !== 'legacy') return
    setRecordSource('server'); setGroupId(null); setStudentId(null); setModal(null); setPage('overview')
  }, [recordSource, serverCutover])
  useEffect(() => { if ((page === 'accounts' || page === 'migration') && !currentUser.is_owner) setPage('overview') }, [currentUser.is_owner, page])
  const group = recordForSource(groupId,recordSource,domainData.groups,data.groups)
  const student = recordForSource(studentId,recordSource,domainData.students,data.students)
  const profileData = student?.serverBacked ? domainData : data
  const focusedTask = (recordSource==='server'?domainData.tasks:data.tasks).find(t => t.id === focusedTaskId) ?? null
  const focusedStudent = (focusedTask?.serverBacked?domainData.students:data.students).find(s=>s.id===focusedTask?.studentId)
  const focusedGroup = (focusedTask?.serverBacked?domainData.groups:data.groups).find(g=>g.id===focusedStudent?.groupId)
  const focusedHomework = focusedTask ? (focusedTask.serverBacked?domainData.homeworks:data.homeworks).filter(homework=>!homework.deletedAt&&homework.items.some(item=>item.taskId===focusedTask.id)).sort((a,b)=>b.createdAt.localeCompare(a.createdAt)).find(homework=>focusedTask.reviewStatus==='pending'?homework.status==='submitted':focusedTask.reviewStatus==='revision'?homework.status==='revision':true) : undefined
  const currentTasks = student ? (student.serverBacked?profileData.tasks.filter(task=>task.studentId===student.id):studentTasks(profileData, student.id)) : []
  const activeGroups = domainData.groups.filter(g => g.status === 'active')
  const hasDemo = data.groups.some(g => g.id.startsWith('demo-'))
  const tasksInActiveGroups = activeTasks(domainData.tasks).filter(t => {
    const s = domainData.students.find(student => student.id === t.studentId)
    return s && domainData.groups.some(g => g.id === s.groupId && g.status === 'active')
  })
  const openPage = (next: Page) => { if(next==='overview'||next==='strategies'||next==='anya'||next==='homework'){setRecordSource('server');setGroupId(null);setStudentId(null)}if(next==='anya'||next==='homework'){void serverDomain.load();void strategyDomain.load();void learningDomain.load()}setPage(next); setReturnPage(null); setSearchOpen(false) }
  const openGroup = (id: string) => { setRecordSource('server');setReturnPage(page==='strategies'?returnPage:page);setPage('strategies'); setGroupId(id); setStudentId(null);if(serverDomain.groups.some(item=>item.id===id))void serverDomain.refreshGroup(id).catch(error=>setNotice({title:'Не удалось обновить группу',description:groupStudentErrorMessage(error)})) }
  const openStudent = (id: string, tab: ProfileTab = 'overview', homeworkId: string | null = null) => { const s = domainData.students.find(v => v.id === id); if (!s) return;setRecordSource('server');if(page!=='strategies')setStudentBackToRoster(false);setReturnPage(page==='strategies'?returnPage:page); setPage('strategies'); setGroupId(s.groupId); setStudentId(id); setProfileTab(tab); setFocusedHomeworkId(homeworkId);setProfileNavigationKey(key=>key+1);void Promise.all([serverDomain.refreshStudent(id),strategyDomain.refreshStudent(id),learningDomain.refreshStudent(id)]).catch(error=>setNotice({title:'Не удалось обновить профиль',description:error instanceof ApiError?learningErrorMessage(error):groupStudentErrorMessage(error)})) }
  const openLegacyStudent = (id: string, tab: ProfileTab = 'overview', homeworkId: string | null = null) => { if(serverCutover||hasServerCutover()){setServerCutover(true);setNotice({title:'Локальная копия доступна только для скачивания',description:'После миграции рабочие данные загружаются с сервера'});return}const s = data.students.find(v=>v.id===id);if(!s)return;setRecordSource('legacy');if(page!=='strategies')setStudentBackToRoster(false);setReturnPage(page==='strategies'?returnPage:page);setPage('strategies');setGroupId(s.groupId);setStudentId(id);setProfileTab(tab);setFocusedHomeworkId(homeworkId);setProfileNavigationKey(key=>key+1) }
  const returnToSource=()=>{if(!returnPage)return;setPage(returnPage);setStudentId(null);setGroupId(null);setReturnPage(null);setStudentBackToRoster(false);setModal(null)}
  const openTask = (id: string) => {const task=recordSource==='legacy'?data.tasks.find(item=>item.id===id):domainData.tasks.find(item=>item.id===id)??data.tasks.find(item=>item.id===id);if(!task)return;if(task.serverBacked){openStudent(task.studentId,'strategy');setRecordSource('server');void strategyDomain.loadHistory(task).catch(error=>setNotice({title:'Не удалось загрузить историю задачи',description:strategyErrorMessage(error)}))}else if(page==='strategies'&&recordSource==='legacy'&&studentId===task.studentId){setProfileTab('strategy');setProfileNavigationKey(key=>key+1)}else openLegacyStudent(task.studentId,'strategy');setFocusedTaskId(id);setModal('taskDetail') }
  const openReview = (id: string) => { const serverHomework=domainData.homeworks.find(h=>h.id===id&&!h.deletedAt);if(serverHomework){openStudent(serverHomework.studentId,'homework',id);return}const homework=data.homeworks.find(h=>h.id===id&&!h.deletedAt); if (homework) openLegacyStudent(homework.studentId,'homework',id) }
  const handleMutationError=(error:unknown)=>{if(error instanceof ApiError&&error.status===409){setModal(null);setNotice({title:'Данные изменились в другой сессии',description:groupStudentErrorMessage(error)});return}setFormError(groupStudentErrorMessage(error));if(error instanceof ApiError&&[403,404].includes(error.status))void serverDomain.load()}
  const saveGroup = async () => { if (!draftGroup?.name.trim()||formPendingRef.current) return;formPendingRef.current=true;setFormPending(true);setFormError('');try{const prepared={...draftGroup,endsAt:draftGroup.durationMonths?addCalendarMonths(draftGroup.startsAt,draftGroup.durationMonths):draftGroup.endsAt};if(formSource==='legacy'){const existing=data.groups.some(item=>item.id===prepared.id);setData(current=>({...current,demo:false,groups:existing?current.groups.map(item=>item.id===prepared.id?prepared:item):[...current.groups,prepared]}));setModal(null);return}const existing=Boolean(prepared.serverBacked);const saved=await serverDomain.saveGroup(prepared);setModal(null);if(!existing){setGroupsView('groups');setGroupsFilter(saved.status);openGroup(saved.id)}}catch(error){handleMutationError(error)}finally{formPendingRef.current=false;setFormPending(false)} }
  const setGroupStatus = async (target: Group, status: GroupStatus) => { if(!target.serverBacked){setData(current=>({...current,demo:false,groups:current.groups.map(item=>item.id===target.id?{...item,status,statusBeforeArchive:status==='archived'?(item.status==='archived'?item.statusBeforeArchive:item.status):item.statusBeforeArchive,actualEndsAt:status==='completed'&&!item.actualEndsAt?today():item.actualEndsAt}:item)}));return}try { await serverDomain.changeGroupStatus(target,status) } catch(error) { setNotice({title:'Не удалось изменить статус группы',description:groupStudentErrorMessage(error)});throw error } }
  const saveStudent = async () => { if (!draftStudent?.name.trim() || !draftStudent.groupId||formPendingRef.current) return;formPendingRef.current=true;setFormPending(true);setFormError('');try{if(formSource==='legacy'){const existing=data.students.some(item=>item.id===draftStudent.id);setData(current=>({...current,demo:false,students:existing?current.students.map(item=>item.id===draftStudent.id?draftStudent:item):[...current.students,draftStudent]}));setRecordSource('legacy');setGroupId(draftStudent.groupId);setStudentId(draftStudent.id);setModal(null);return}const existing=Boolean(draftStudent.serverBacked);const saved=await serverDomain.saveStudent(draftStudent);setModal(null);if(!existing){setRecordSource('server');setPage('strategies');setGroupId(saved.groupId);setStudentId(saved.id);setProfileTab('overview');setProfileNavigationKey(key=>key+1)}}catch(error){handleMutationError(error)}finally{formPendingRef.current=false;setFormPending(false)} }
  const patchStudent = (patch: Partial<Student>) => { if (!student) return;if(student.serverBacked){void serverDomain.saveStudent({...student,...patch}).catch(error=>setNotice({title:'Не удалось сохранить профиль',description:groupStudentErrorMessage(error)}));return} setData(d => ({ ...d, demo: false, students: d.students.map(s => s.id === student.id ? { ...s, ...patch } : s) })) }
  const addMeeting = async (meeting: Meeting) => {if(meeting.serverBacked||student?.serverBacked){try{await learningDomain.createMeeting(meeting.studentId,{date:meeting.date,title:meeting.title.trim(),summary:meeting.summary,notes:meeting.notes??''})}catch(error){throw learningUiError(error)}return}setData(d => ({ ...d, demo: false, meetings: [...d.meetings, meeting] }))}
  const updateMeeting = async (meeting:Meeting) => {if(meeting.serverBacked){try{await learningDomain.updateMeeting(meeting,{date:meeting.date,title:meeting.title.trim(),summary:meeting.summary,notes:meeting.notes??''})}catch(error){throw learningUiError(error)}return}setData(d=>({...d,meetings:d.meetings.map(item=>item.id===meeting.id?meeting:item)}))}
  const deleteMeeting = async (id: string) => {const meeting=domainData.meetings.find(item=>item.id===id);if(meeting?.serverBacked){try{await learningDomain.setMeetingArchived(meeting,true)}catch(error){throw learningUiError(error)}return}setData(d => ({ ...d, demo: false, meetings: d.meetings.filter(m => m.id !== id) }))}
  const restoreMeeting=async(id:string)=>{const meeting=domainData.meetings.find(item=>item.id===id);if(!meeting)return;try{await learningDomain.setMeetingArchived(meeting,false)}catch(error){setNotice({title:'Не удалось восстановить встречу',description:learningErrorMessage(error)})}}
  const saveTask = async () => {
    if (!draftTask?.title.trim()) return
    const serverManaged=Boolean(draftTask.serverBacked||domainData.students.some(item=>item.id===draftTask.studentId))
    if(serverManaged){if(formPendingRef.current)return;formPendingRef.current=true;setFormPending(true);setFormError('');try{await (draftTask.serverBacked?strategyDomain.updateTask(draftTask):strategyDomain.createTask(draftTask));setModal(null)}catch(error){setFormError(strategyErrorMessage(error))}finally{formPendingRef.current=false;setFormPending(false)}return}
    if(serverCutover||hasServerCutover()){setServerCutover(true);setModal(null);setNotice({title:'Локальные данные доступны только для скачивания',description:'После миграции изменения сохраняются только на сервере'});return}
    if (['pending','revision'].includes(draftTask.reviewStatus) && data.tasks.find(task=>task.id===draftTask.id)?.studyStatus !== draftTask.studyStatus) {
      setNotice({title:'Статус пока недоступен',description:'Сначала завершите проверку или доработку в домашнем задании'})
      return
    }
    const now = new Date().toISOString()
    const task = { ...draftTask, status:draftTask.studyStatus==='done'?'done' as TaskStatus:draftTask.studyStatus==='not_started'?'backlog' as TaskStatus:'progress' as TaskStatus, reviewStatus:draftTask.studyStatus==='done'?'accepted' as const:draftTask.reviewStatus==='accepted'?'none' as const:draftTask.reviewStatus, updatedAt: now }
    const next = { ...data, demo: false, tasks: data.tasks.some(item => item.id === task.id) ? data.tasks.map(item => item.id === task.id ? {...task, history:[...item.history,{at:now,label:item.studyStatus!==task.studyStatus?`Статус: ${STUDY_STATUS[task.studyStatus]}`:'Данные задачи обновлены'}]} : item) : [...data.tasks, {...task,history:[{at:now,label:'Задача создана'}]}], students: data.students.map(item => item.id === task.studentId ? { ...item, strategyUpdatedAt: now } : item) }
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(next))
    } catch {
      setSaveError(true)
      return
    }
    setData(next)
    setModal(null)
  }
  const changeTask = (id: string, patch: Partial<StrategyTask>, label = 'Задача обновлена') => setData(d => { const now = new Date().toISOString(); const task = d.tasks.find(t => t.id === id); return { ...d, demo: false, tasks: d.tasks.map(t => t.id === id ? { ...t, ...patch, updatedAt: now, history:[...t.history,{at:now,label}] } : t), students: d.students.map(s => s.id === task?.studentId ? { ...s, strategyUpdatedAt: now } : s) } })
  const changeStudyStatus = (id:string,studyStatus:StudyStatus) => { const task=domainData.tasks.find(item=>item.id===id)??data.tasks.find(t=>t.id===id);if(!task)return;if(task.serverBacked){void strategyDomain.changeStatus(task,studyStatus).catch(error=>setNotice({title:'Не удалось изменить статус',description:strategyErrorMessage(error)}));return}if(studyStatus!==task.studyStatus&&['pending','revision'].includes(task.reviewStatus)){setNotice({title:'Статус пока недоступен',description:'Сначала завершите проверку или доработку в домашнем задании'});return} const status:TaskStatus=studyStatus==='done'?'done':studyStatus==='not_started'?'backlog':'progress'; const reviewStatus=studyStatus==='done'?'accepted':task.reviewStatus==='accepted'?'none':task.reviewStatus;changeTask(id,{studyStatus,status,reviewStatus},`Статус: ${STUDY_STATUS[studyStatus]}`) }
  const addSection = (title:string) => { if(!student)return;if(student.serverBacked){void strategyDomain.createSection(student.id,title).catch(error=>setNotice({title:'Не удалось добавить раздел',description:strategyErrorMessage(error)}));return}setData(d=>({...d,sections:[...d.sections,{id:uid(),studentId:student.id,title,order:d.sections.filter(s=>s.studentId===student.id).length,createdAt:new Date().toISOString()}]})) }
  const renameSection = (id:string,title:string) => {const section=domainData.sections.find(item=>item.id===id);if(section?.serverBacked){void strategyDomain.renameSection(section,title).catch(error=>setNotice({title:'Не удалось переименовать раздел',description:strategyErrorMessage(error)}));return}setData(d=>({...d,sections:d.sections.map(s=>s.id===id?{...s,title}:s)}))}
  const deleteSection = (id:string) => { if(data.tasks.some(task=>task.sectionId===id)){setNotice({title:'Раздел хранит историю задач',description:'Переместите активные задачи. Архивные связи сохраняются и не позволяют удалить раздел'});return}setData(d=>({...d,sections:d.sections.filter(s=>s.id!==id)})) }
  const changeSection = (id:string,sectionId:string) => {const task=domainData.tasks.find(item=>item.id===id);if(task?.serverBacked){setNotice({title:'Перенос между разделами пока недоступен',description:'Backend не поддерживает безопасное перемещение задачи в другой раздел'});return}changeTask(id,{sectionId,order:Math.max(0,...data.tasks.filter(t=>t.sectionId===sectionId).map(t=>t.order))+1},'Перемещена в другой раздел')}
  const createHomework = async (taskIds: string[], title: string, text: string):Promise<string> => { if (!student || !taskIds.length) return '';if(student.serverBacked){try{return (await learningDomain.createHomework(student.id,{title:title.trim()||'Домашнее задание',description:text,task_ids:taskIds,links:{},due_at:null})).id}catch(error){throw learningUiError(error)}} const items = taskIds.map(id => data.tasks.find(t => t.id === id)).filter((t):t is StrategyTask => Boolean(t)).map(t => ({taskId:t.id,title:t.title,description:homeworkDescription(t),url:t.url,materials:[...t.materials],dueAt:t.dueAt})); const now = new Date().toISOString(); const id=uid(); const homework: Homework = {id,studentId:student.id,title:title.trim()||'Домашнее задание',text:text.trim()||homeworkText(title,items,''),items,status:'draft',issuedAt:'',submittedAt:'',workUrl:'',comment:'',dueAt:'',createdAt:now}; setData(d => ({...d,demo:false,homeworks:[...d.homeworks,homework]})); return id }
  const updateHomework = async (id: string, patch: Partial<Homework>) => {const homework=domainData.homeworks.find(item=>item.id===id);if(homework?.serverBacked){try{let current=homework;if((patch.title!==undefined||patch.text!==undefined||patch.dueAt!==undefined||patch.links!==undefined)&&homework.status==='draft')current=await learningDomain.updateHomework(homework,{...(patch.title!==undefined?{title:patch.title}:{}),...(patch.text!==undefined?{description:patch.text}:{}),...(patch.dueAt!==undefined?{due_at:patch.dueAt||null}:{}),...(patch.links!==undefined?{links:patch.links}:{})});if(patch.status&&patch.status!==current.status){const submissionUrl=safeExternalUrl(patch.workUrl??current.workUrl);await learningDomain.transitionHomework(current,{status:patch.status,...(patch.status==='submitted'?{submission_text:patch.submissionText??current.submissionText??'',submission_links:submissionUrl?{work:submissionUrl}:{}}:{}),...(['revision','accepted'].includes(patch.status)?{curator_feedback:patch.comment??current.comment}:{})})}}catch(error){throw learningUiError(error)}return}setData(d => applyHomeworkPatch(d,id,patch))}
  const deleteHomework = async (id:string) => {const homework=domainData.homeworks.find(item=>item.id===id);if(homework?.serverBacked){try{await learningDomain.setHomeworkArchived(homework,true)}catch(error){throw learningUiError(error)}return}setData(d=>({...d,homeworks:d.homeworks.map(h=>h.id===id?{...h,deletedAt:new Date().toISOString()}:h)}))}
  const restoreHomework=async(id:string)=>{const homework=domainData.homeworks.find(item=>item.id===id);if(homework?.serverBacked){try{await learningDomain.setHomeworkArchived(homework,false)}catch(error){throw learningUiError(error)}return}setData(d=>({...d,homeworks:d.homeworks.map(item=>item.id===id?{...item,deletedAt:''}:item)}))}
  const loadHomeworkHistory=async(id:string)=>{const homework=domainData.homeworks.find(item=>item.id===id);if(!homework)return;try{await learningDomain.loadHomeworkHistory(homework)}catch(error){throw learningUiError(error)}}
  const setApproval = async (id: string, status: ApprovalStatus, comment?:string) => {const task=domainData.tasks.find(item=>item.id===id);if(task?.serverBacked){try{await strategyDomain.transitionApproval(task,status,comment)}catch(error){setNotice({title:'Не удалось изменить согласование',description:strategyErrorMessage(error)});if(error instanceof ApiError&&[403,404].includes(error.status)){strategyDomain.evictStudent(task.studentId);void serverDomain.load()}}return}setData(d=>applyApprovalStatus(d,id,status))}
  const recallTaskApproval = async (id:string) => {const task=domainData.tasks.find(item=>item.id===id);if(task?.serverBacked){try{await strategyDomain.transitionApproval(task,'to_send',task.approvalComment)}catch(error){setNotice({title:'Не удалось вернуть согласование',description:strategyErrorMessage(error)});if(error instanceof ApiError&&[403,404].includes(error.status)){strategyDomain.evictStudent(task.studentId);void serverDomain.load()}}return}setData(d=>recallApproval(d,id))}
  const moveOrder = (task: StrategyTask, delta: number) => {if(task.serverBacked){void strategyDomain.reorderTasks(task,delta).catch(error=>setNotice({title:'Не удалось изменить порядок задач',description:strategyErrorMessage(error)}));return} const peers = currentTasks.filter(t => t.sectionId === task.sectionId).sort((a,b) => a.order - b.order); const i = peers.findIndex(t => t.id === task.id); const other = peers[i + delta]; if (!other) return; setData(d => ({ ...d, demo: false, tasks: d.tasks.map(t => t.id === task.id ? { ...t, order: other.order } : t.id === other.id ? { ...t, order: task.order } : t) })) }
  const moveSection=(section:StrategySection,delta:number)=>{if(!section.serverBacked)return;const ordered=domainData.sections.filter(item=>item.studentId===section.studentId).sort((a,b)=>a.order-b.order);const index=ordered.findIndex(item=>item.id===section.id);const target=ordered[index+delta];if(!target)return;[ordered[index],ordered[index+delta]]=[ordered[index+delta],ordered[index]];void strategyDomain.reorderSections(section.studentId,ordered).catch(error=>setNotice({title:'Не удалось изменить порядок разделов',description:strategyErrorMessage(error)}))}
  const removeGroup = (g: Group) => { if(g.serverBacked){setConfirmState({title:'Переместить группу в архив?',description:`Группа «${g.name}» и её состав сохранятся. Группу можно будет восстановить`,confirmLabel:'Переместить в архив',action:()=>setGroupStatus(g,'archived'),getErrorMessage:groupStudentErrorMessage});return}if (data.students.some(s => s.groupId === g.id)) { setNotice({title:'Нельзя удалить группу',description:'Сначала переместите или удалите учениц этой группы'}); return } setConfirmState({title:'Удалить группу?',description:`Группа «${g.name}» будет удалена`,confirmLabel:'Удалить группу',danger:true,action:()=>{setData(d=>({...d,demo:false,groups:d.groups.filter(x=>x.id!==g.id)}));setGroupId(null)}}) }
  const removeStudent = (s: Student) => {if(s.serverBacked){setConfirmState({title:'Переместить профиль в архив?',description:`Профиль «${s.name}», аккаунт и учебная история сохранятся`,confirmLabel:'Переместить в архив',action:async()=>{await serverDomain.setStudentArchived(s,true)},getErrorMessage:groupStudentErrorMessage});return}setConfirmState({title:'Удалить ученицу и её данные?',description:`Профиль «${s.name}», стратегия, домашние задания и история встреч будут удалены без возможности восстановления`,confirmLabel:'Удалить ученицу',danger:true,action:()=>{setData(d => ({ ...d, demo: false, students: d.students.filter(x => x.id !== s.id), sections:d.sections.filter(section=>section.studentId!==s.id), tasks: d.tasks.filter(t => t.studentId !== s.id), meetings: d.meetings.filter(m => m.studentId !== s.id), homeworks:d.homeworks.filter(h=>h.studentId!==s.id) }));setStudentId(null)}})}
  const restoreStudent=(s:Student)=>setConfirmState({title:'Восстановить профиль?',description:`Профиль «${s.name}» снова появится среди активных`,confirmLabel:'Восстановить',action:async()=>{await serverDomain.setStudentArchived(s,false)},getErrorMessage:groupStudentErrorMessage})
  const removeTask = (task: StrategyTask) => {
    if(task.serverBacked){const restoring=Boolean(task.archivedAt);setConfirmState({title:restoring?'Восстановить задачу?':'Переместить задачу в архив?',description:restoring?`«${task.title}» снова появится в активной стратегии`:`«${task.title}» сохранится вместе с историей и согласованием`,confirmLabel:restoring?'Восстановить':'Переместить в архив',action:async()=>{await strategyDomain.setTaskArchived(task,!restoring);setModal(null)},getErrorMessage:strategyErrorMessage});return}
    if(serverCutover||hasServerCutover()){setServerCutover(true);setModal(null);setNotice({title:'Локальные данные доступны только для скачивания',description:'После миграции изменения сохраняются только на сервере'});return}
    const linkedHomeworks=data.homeworks.filter(homework=>homework.items.some(item=>item.taskId===task.id)).length
    const linkedLabel=linkedHomeworks?` Связанные домашние задания (${linkedHomeworks}) и их снимки останутся в истории.`:''
    setConfirmState({title:'Удалить задачу?',description:`«${task.title}» исчезнет из активной стратегии и очереди Ани.${linkedLabel}`,confirmLabel:'Удалить задачу',danger:true,action:()=>{
      const next=archiveTask(dataRef.current,task.id)
      localStorage.setItem(STORAGE_KEY,JSON.stringify(next))
      dataRef.current=next;setData(next);setModal(null)
    }})
  }
  const exportBackup = () => { const raw=localStorage.getItem(STORAGE_KEY)??JSON.stringify(data,null,2);const blob = new Blob([raw], { type: 'application/json' }); const url = URL.createObjectURL(blob); const a = document.createElement('a'); a.href = url; a.download = `kuratorskaya-browser-backup-${today()}.json`; a.click(); URL.revokeObjectURL(url) }
  const exportBeforeImport = () => { const raw=localStorage.getItem(`${STORAGE_KEY}-before-strategies-import`);if(!raw)return;const blob=new Blob([raw],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`kuratorskaya-before-import-${today()}.json`;a.click();URL.revokeObjectURL(url) }
  const exportBeforeSections = () => { const raw=localStorage.getItem(PRE_SECTION_BACKUP_KEY);if(!raw)return;const blob=new Blob([raw],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`kuratorskaya-before-section-strategies-${today()}.json`;a.click();URL.revokeObjectURL(url) }
  const completeCutover=async()=>{setServerCutover(true);setRecordSource('server');setGroupId(null);setStudentId(null);setModal(null);await Promise.allSettled([serverDomain.load(),strategyDomain.load(),learningDomain.load()])}

  const attention = useMemo(() => domainData.students.filter(s => domainData.groups.some(g => g.id === s.groupId && g.status === 'active')).map(s => {
    const tasks = studentTasks(domainData, s.id)
    const blockers = tasks.filter(t => t.blocker && taskColumn(t) !== 'done').length
    const stale = Date.now() - new Date(s.strategyUpdatedAt).getTime() > 14 * 86400000
    return { student: s, blockers, stale }
  }).filter(x => x.blockers || x.stale).sort((a,b) => (b.blockers + Number(b.stale)) - (a.blockers + Number(a.stale))), [domainData])
  const upcoming = tasksInActiveGroups.filter(t => t.studyStatus === 'in_progress').sort((a,b) => a.order-b.order)
  const normalizedSearch = searchTerm.trim().toLocaleLowerCase('ru-RU')
  const foundStudents = normalizedSearch ? domainData.students.filter(s => s.name.toLocaleLowerCase('ru-RU').includes(normalizedSearch)).slice(0, 5) : []
  const foundGroups = normalizedSearch ? domainData.groups.filter(g => g.name.toLocaleLowerCase('ru-RU').includes(normalizedSearch)).slice(0, 4) : []
  const domainPage=page==='overview'||page==='homework'||(page==='strategies'&&recordSource==='server')
  const canCreateGroups=currentUser.role==='admin'&&currentUser.is_active&&!currentUser.must_change_password
  const currentGroupWritable=Boolean(group&&(!group.serverBacked||canWriteGroup(currentUser,group)))
  const currentStudentWritable=Boolean(student&&(!student.serverBacked||canWriteStudent(currentUser,student,domainData.groups)))
  const focusedTaskWritable=Boolean(focusedTask&&(!focusedTask.serverBacked||focusedStudent&&canWriteStudent(currentUser,focusedStudent,domainData.groups)))
  const editGroup=async(target:Group)=>{setFormSource(target.serverBacked?'server':'legacy');setFormError('');try{const detail=target.serverBacked?await serverDomain.refreshGroup(target.id):target;setDraftGroup({...detail});setModal('group')}catch(error){setNotice({title:'Не удалось открыть редактирование',description:groupStudentErrorMessage(error)})}}
  const editStudent=async(target:Student)=>{setFormSource(target.serverBacked?'server':'legacy');setFormError('');try{const detail=target.serverBacked?await serverDomain.refreshStudent(target.id):target;setDraftStudent({...detail,links:{...detail.links}});setModal('student')}catch(error){setNotice({title:'Не удалось открыть редактирование',description:groupStudentErrorMessage(error)})}}
  return <div className={`app-shell ${page === 'overview' ? 'overview-shell' : ''}`}>
    <FlowBackground className="app-flow-background"/>
    <header className="workspace-toolbar">
      <div className="workspace-toolbar-left"><button className="brand-logo" aria-label="Кураторская — обзор" title="Обзор" onClick={() => openPage('overview')}><img src="/brand-star.svg" width="28" height="28" alt=""/><span>Кураторская</span></button></div>
      <nav className="toolbar-nav" aria-label="Основная навигация">{visibleNav.map(({ id, label, icon: Icon }) => <button key={id} className={page === id ? 'active' : ''} aria-current={page===id?'page':undefined} title={label} onClick={() => openPage(id)}><Icon size={17}/><span>{label}</span></button>)}</nav>
      <div className="workspace-toolbar-right"><div className="group-switch"><Select aria-label="Перейти к группе" value={page==='strategies'&&recordSource==='server'&&domainData.groups.some(item=>item.id===groupId)?groupId ?? '':''} onChange={e => e.target.value ? openGroup(e.target.value) : (setRecordSource('server'),setGroupId(null),setStudentId(null),setPage('strategies'))}><option value="">Все группы</option>{domainData.groups.map(g => <option key={g.id} value={g.id}>{g.name}</option>)}</Select></div><button className="toolbar-icon" aria-label="Поиск" title="Поиск" onClick={() => setSearchOpen(v => !v)}><Search size={16} weight="regular"/></button><button className="toolbar-icon" aria-label="Данные и копии" title="Данные и копии" onClick={() => setModal('backup')}><Settings2 size={16} weight="regular"/></button><span className="toolbar-user" title={`Аккаунт: ${currentUser.login}`}>{currentUser.login}</span><button className="toolbar-icon" aria-label="Выйти" title="Выйти" disabled={logoutPending} onClick={() => { setLogoutPending(true); void logout().catch(() => setNotice({title:'Не удалось выйти',description:'Сессия остаётся активной. Проверьте соединение с сервером и повторите попытку'})).finally(() => setLogoutPending(false)) }}><SignOut size={17} weight="regular"/></button></div>
      <AnimatePresence initial={false}>{searchOpen && <motion.div key="search" className="toolbar-search-panel" {...calm.popover}><input autoFocus aria-label="Поиск группы или ученицы" placeholder="Группа или ученица" value={searchTerm} onChange={e => setSearchTerm(e.target.value)}/>{normalizedSearch && <div className="toolbar-search-results">{foundStudents.map(s => <button key={s.id} onClick={() => { openStudent(s.id); setSearchOpen(false); setSearchTerm('') }}><strong>{s.name}</strong><small>{domainData.groups.find(group=>group.id===s.groupId)?.name||'Группа не найдена'} · ученица</small></button>)}{foundGroups.map(g => <button key={g.id} onClick={() => { openGroup(g.id); setSearchOpen(false); setSearchTerm('') }}><strong>{g.name}</strong><small>Группа</small></button>)}{!foundStudents.length && !foundGroups.length && <p>Ничего не найдено</p>}</div>}</motion.div>}</AnimatePresence>
    </header>
    <main className={`main ${page === 'overview' ? 'overview-main' : ''}`}>
      {saveError&&!serverCutover && <div className="save-error">Не удалось сохранить данные в браузере. Экспортируйте резервную копию и проверьте свободное место</div>}
      {hasDemo&&!domainPage&&!serverCutover && <div className="demo-banner"><span><strong>Демонстрационные данные</strong> Четыре тестовые группы и профили можно редактировать</span><button onClick={() => setConfirmState({title:'Убрать демонстрационные данные?',description:'Тестовые группы, ученицы, задачи, домашние задания и встречи будут удалены. Ваши собственные записи сохранятся',confirmLabel:'Убрать пример',danger:true,action:()=>{setData(d => ({ ...d, demo: false, groups: d.groups.filter(g => !g.id.startsWith('demo-')), students: d.students.filter(s => !s.id.startsWith('demo-')), tasks: d.tasks.filter(t => !t.id.startsWith('demo-')), meetings: d.meetings.filter(m => !m.id.startsWith('demo-')),homeworks:d.homeworks.filter(h=>!h.studentId.startsWith('demo-')) }));setGroupId(null);setStudentId(null);setPage('overview')}})}>Убрать пример</button></div>}
      <div className="content"><div className="page-motion">
        {domainPage&&(serverDomain.status==='loading'||(page==='overview'&&strategyDomain.status==='loading'))&&<div className="account-state" role="status"><span className="account-spinner"/>Загружаем группы, профили и стратегии…</div>}
        {domainPage&&serverDomain.status==='error'&&<div className="account-state account-state-error" role="alert"><strong>Не удалось загрузить группы и профили</strong><p>{groupStudentErrorMessage(serverDomain.error)}</p><button className="btn secondary" onClick={()=>void serverDomain.load()}>Повторить</button></div>}
        {page==='overview'&&strategyDomain.status==='error'&&<div className="account-state account-state-error" role="alert"><strong>Не удалось загрузить стратегии</strong><p>{strategyErrorMessage(strategyDomain.error)}</p><button className="btn secondary" onClick={()=>void strategyDomain.load()}>Повторить</button></div>}
        {page === 'overview'&&serverDomain.status==='ready'&&strategyDomain.status==='ready' && <PlanOverview data={domainData} activeGroups={activeGroups} tasks={tasksInActiveGroups} attention={attention} upcoming={upcoming} onGroup={openGroup} onStudent={openStudent} onTask={openTask} onReview={openReview} onNewGroup={() => { setFormSource('server');setFormError('');setDraftGroup(newGroup()); setModal('group') }} onStrategies={() => {setRecordSource('server');setGroupId(null);setStudentId(null);setPage('strategies')}} onAnya={() => openPage('anya')} onHomework={() => openPage('homework')}/>}
        {page === 'strategies'&&recordSource==='server'&&serverDomain.status==='ready' && !group && <GroupsPage data={domainData} view={groupsView} onView={setGroupsView} filter={groupsFilter} onFilter={setGroupsFilter} onOpen={openGroup} onStudent={id=>{setStudentBackToRoster(true);openStudent(id)}} canCreate={canCreateGroups} canWrite={target=>canWriteGroup(currentUser,target)} onNew={() => { setFormSource('server');setFormError('');setDraftGroup(newGroup()); setModal('group') }} onEdit={g => {void editGroup(g)}} onStatus={(target,status)=>{void setGroupStatus(target,status).catch(()=>undefined)}} onDelete={removeGroup}/>}
        {page === 'strategies'&&(recordSource==='legacy'||serverDomain.status==='ready') && group && !student && <GroupDetailPage data={group.serverBacked?domainData:data} group={group} canWrite={currentGroupWritable} onBack={returnPage?returnToSource:()=>{setRecordSource('server');setGroupId(null)}} backLabel={returnPage?`Вернуться: ${visibleNav.find(item=>item.id===returnPage)?.label}`:'Все группы'} onStudent={id=>{setStudentBackToRoster(false);if(recordSource==='legacy')openLegacyStudent(id);else openStudent(id)}} onNewStudent={() => { setFormSource(group.serverBacked?'server':'legacy');setFormError('');setDraftStudent(newStudent(group.id)); setModal('student') }} onEditGroup={() => {void editGroup(group)}} onStatus={status => {void setGroupStatus(group,status).catch(()=>undefined)}}/>}
        {page==='strategies'&&recordSource==='server'&&student&&strategyDomain.status==='loading'&&<div className="account-state" role="status"><span className="account-spinner"/>Загружаем стратегию…</div>}
        {page==='strategies'&&recordSource==='server'&&student&&strategyDomain.status==='error'&&<div className="account-state account-state-error" role="alert"><strong>Не удалось загрузить стратегию</strong><p>{strategyErrorMessage(strategyDomain.error)}</p><button className="btn secondary" onClick={()=>void strategyDomain.refreshStudent(student.id)}>Повторить</button></div>}
        {page === 'strategies'&&(recordSource==='legacy'||serverDomain.status==='ready'&&strategyDomain.status==='ready') && student && <ProfilePage key={`${recordSource}-${student.id}`} data={profileData} student={student} tasks={currentTasks} initialTab={profileTab} navigationKey={profileNavigationKey} focusedHomeworkId={focusedHomeworkId} onTabChange={setProfileTab} onBack={() => {setStudentId(null);setStudentBackToRoster(false)}} onAllGroups={() => {setRecordSource('server');setStudentId(null);setGroupId(null);setGroupsView('groups');setReturnPage(null);setStudentBackToRoster(false)}} onReturn={returnPage?returnToSource:studentBackToRoster?()=>{setRecordSource('server');setStudentId(null);setGroupId(null);setGroupsView('students');setStudentBackToRoster(false)}:undefined} returnLabel={returnPage?visibleNav.find(item=>item.id===returnPage)?.label:studentBackToRoster?'список учениц':undefined} serverManaged={student.serverBacked} hasStrategy={!student.serverBacked||Boolean(strategyDomain.strategies[student.id])} onCreateStrategy={()=>{void strategyDomain.ensureStrategy(student.id).catch(error=>setNotice({title:'Не удалось создать стратегию',description:strategyErrorMessage(error)}))}} canEdit={currentStudentWritable} accountPanel={student.serverBacked?<StudentAccountPanel studentId={student.id} canManage={currentStudentWritable}/>:undefined} meetingLoading={Boolean(student.serverBacked&&learningDomain.meetingStatus==='loading')} meetingLoadError={student.serverBacked&&learningDomain.meetingErrorsByStudent.has(student.id)?learningErrorMessage(learningDomain.meetingErrorsByStudent.get(student.id)):''} homeworkLoading={Boolean(student.serverBacked&&learningDomain.homeworkStatus==='loading')} homeworkLoadError={student.serverBacked&&learningDomain.homeworkErrorsByStudent.has(student.id)?learningErrorMessage(learningDomain.homeworkErrorsByStudent.get(student.id)):''} onRetryMeetings={()=>void learningDomain.refreshMeetings(student.id).catch(()=>undefined)} onRetryHomeworks={() => void Promise.all([learningDomain.refreshHomeworks(student.id), strategyDomain.refreshStudent(student.id)]).catch(() => undefined)} onEdit={() => {void editStudent(student)}} onDelete={() => removeStudent(student)} onRestore={()=>restoreStudent(student)} onNewTask={sectionId => { const order=Math.max(-1,...currentTasks.filter(task=>!sectionId||task.sectionId===sectionId).map(task=>task.order))+1;setFormError('');setDraftTask({...newTask(student.id,order,student.stage),sectionId:sectionId||''});setModal('task') }} onEditTask={openTask} onStudyStatus={changeStudyStatus} onMove={moveOrder} onMoveSection={moveSection} onAddSection={addSection} onRenameSection={renameSection} onDeleteSection={deleteSection} onChangeSection={changeSection} onPatch={patchStudent} onAddMeeting={addMeeting} onUpdateMeeting={updateMeeting} onDeleteMeeting={deleteMeeting} onRestoreMeeting={restoreMeeting} onCreateHomework={createHomework} onUpdateHomework={updateHomework} onDeleteHomework={deleteHomework} onRestoreHomework={restoreHomework} onHomeworkHistory={loadHomeworkHistory}/>}
        {page === 'anya' && <AnyaPage data={domainData} serverManaged loading={serverDomain.status==='loading'||strategyDomain.status==='loading'} error={serverDomain.status==='error'?groupStudentErrorMessage(serverDomain.error):strategyDomain.status==='error'?strategyErrorMessage(strategyDomain.error):''} partialErrorCount={serverDomain.partialErrorCount+strategyDomain.partialErrorCount} onRetry={()=>{void serverDomain.load();void strategyDomain.load()}} onStudent={id=>openStudent(id,'strategy')} onTask={openTask} onApproval={setApproval} onRecall={recallTaskApproval} onComment={()=>undefined} onType={()=>undefined} onMaterial={()=>undefined} canWriteTask={task=>{const target=domainData.students.find(item=>item.id===task.studentId);return Boolean(target&&canWriteStudent(currentUser,target,domainData.groups))}}/>}
        {page === 'homework' && <HomeworkPage data={domainData} serverManaged loading={serverDomain.status==='loading'||strategyDomain.status==='loading'||learningDomain.homeworkStatus==='loading'} error={serverDomain.status==='error'?groupStudentErrorMessage(serverDomain.error):strategyDomain.status==='error'?strategyErrorMessage(strategyDomain.error):learningDomain.homeworkStatus==='error'?learningErrorMessage(learningDomain.homeworkError):''} partialErrorCount={serverDomain.partialErrorCount+strategyDomain.partialErrorCount+learningDomain.homeworkPartialErrorCount} onRetry={()=>{void serverDomain.load();void strategyDomain.load();void learningDomain.loadHomeworks()}} onStudent={(id,homeworkId)=>openStudent(id,'homework',homeworkId)} onTask={openTask} onUpdate={updateHomework} onDelete={deleteHomework} onRestore={restoreHomework} onHistory={loadHomeworkHistory} canWriteHomework={homework=>{const target=domainData.students.find(item=>item.id===homework.studentId);return Boolean(target&&canWriteStudent(currentUser,target,domainData.groups))}}/>}
        {page === 'prompts' && <Suspense fallback={<div className="knowledge-loading">Загружаем библиотеку…</div>}><KnowledgePage kind="prompts"/></Suspense>}
        {page === 'textbook' && <Suspense fallback={<div className="knowledge-loading">Загружаем учебник…</div>}><KnowledgePage kind="chapters"/></Suspense>}
        {page === 'accounts' && <AccountAdminPage currentUser={currentUser} onRefreshUser={refreshCurrentUser}/>}
        {page === 'migration' && <MigrationPage currentUser={currentUser} onCutover={completeCutover}/>}
      </div></div>
    </main>
    <Dialog open={modal === 'group'&&Boolean(draftGroup)} title={draftGroup&&(draftGroup.serverBacked||data.groups.some(item=>item.id===draftGroup.id)) ? 'Редактировать группу' : 'Новая группа'} onClose={() => {if(!formPending)setModal(null)}} dismissible={!formPending}>{draftGroup&&<GroupForm draft={draftGroup} setDraft={setDraftGroup} onSave={()=>{void saveGroup()}} onCancel={() => setModal(null)} pending={formPending} error={formError}/>}</Dialog>
    <Dialog open={modal === 'student'&&Boolean(draftStudent)} title={draftStudent&&(draftStudent.serverBacked||data.students.some(item=>item.id===draftStudent.id)) ? 'Профиль ученицы' : 'Новая ученица'} onClose={() => {if(!formPending)setModal(null)}} dismissible={!formPending} wide>{draftStudent&&<StudentForm draft={draftStudent} setDraft={setDraftStudent} groups={formSource==='legacy'?data.groups:domainData.groups} onSave={()=>{void saveStudent()}} onCancel={() => setModal(null)} pending={formPending} error={formError} groupLocked photoUploadEnabled={formSource==='legacy'}/>}</Dialog>
    <Dialog open={modal === 'taskDetail'&&Boolean(focusedTask)} title={focusedTask&&hasTechnicalUntitledTitle(focusedTask)?'Задача':focusedTask?.title||'Задача'} onClose={() => setModal(null)} wide>{focusedTask&&<TaskDetail task={focusedTask} studentName={focusedStudent?.name||''} groupName={focusedGroup?.name||''} sectionTitle={(focusedTask.serverBacked?domainData.sections:data.sections).find(section=>section.id===focusedTask.sectionId)?.title} onStatus={status=>changeStudyStatus(focusedTask.id,status)} onPrepareApproval={()=>{if(focusedTask.serverBacked){void strategyDomain.createApproval(focusedTask).catch(error=>setNotice({title:'Не удалось создать согласование',description:strategyErrorMessage(error)}));return}changeTask(focusedTask.id,{approvalStatus:'to_send'},'Подготовлено согласование с Аней')}} homeworkTitle={focusedHomework?.title} onHomework={focusedHomework?()=>{setModal(null);setFocusedHomeworkId(focusedHomework.id);setProfileTab('homework');setProfileNavigationKey(key=>key+1)}:undefined} onEdit={()=>{setFormError('');setDraftTask({...focusedTask});setModal('task')}} canEdit={focusedTaskWritable}/>}</Dialog>
    <Dialog open={modal === 'task'&&Boolean(draftTask)} title={draftTask&&(draftTask.serverBacked||data.tasks.some(task=>task.id===draftTask.id))?'Редактировать задачу':'Новая задача'} onClose={()=>{if(!formPending)setModal(null)}} dismissible={!formPending} wide>{draftTask&&<TaskForm draft={draftTask} setDraft={setDraftTask} sections={(draftTask.serverBacked||domainData.students.some(item=>item.id===draftTask.studentId)?domainData.sections:data.sections).filter(section=>section.studentId===draftTask.studentId)} existing={Boolean(draftTask.serverBacked||data.tasks.some(task=>task.id===draftTask.id))} serverManaged={Boolean(draftTask.serverBacked||domainData.students.some(item=>item.id===draftTask.studentId))} pending={formPending} error={formError} onSave={()=>{void saveTask()}} onCancel={()=>setModal(null)} onDelete={()=>removeTask(draftTask)}/>}</Dialog>
    <Dialog open={modal === 'backup'} title="Данные и резервные копии" onClose={() => setModal(null)}><div className="backup-content"><p>{serverCutover?'Рабочие данные загружаются только с сервера. Локальные копии сохранены без изменений и доступны для скачивания':'Группы и профили загружаются с сервера. Локальная копия сохраняется отдельно до подтверждённой миграции'}</p><button className="btn primary full" onClick={exportBackup}><Download size={17}/> Скачать локальную копию из браузера</button>{localStorage.getItem(PRE_SECTION_BACKUP_KEY)&&<button className="btn secondary full" onClick={exportBeforeSections}><Download size={17}/> Скачать копию до обновления стратегий</button>}{localStorage.getItem(`${STORAGE_KEY}-before-strategies-import`)&&<button className="btn secondary full" onClick={exportBeforeImport}><Download size={17}/> Скачать копию до импорта стратегий</button>}{currentUser.is_owner&&<button className="btn secondary full" onClick={() => {setModal(null);openPage('migration')}}><Database size={17}/> Открыть миграцию и логическую серверную копию</button>}{Boolean(data.importConflicts?.length)&&<div><strong>Требуют сверки в локальной копии</strong><p>Подробности доступны только в исходной локальной копии и не переносятся автоматически</p></div>}</div></Dialog>
    {confirmState?.danger?<DeleteConfirmDialog open title={confirmState.title} description={confirmState.description} confirmLabel={confirmState.confirmLabel} getErrorMessage={confirmState.getErrorMessage} onConfirm={confirmState.action} onClose={()=>setConfirmState(null)}/>:<ConfirmDialog open={Boolean(confirmState)} title={confirmState?.title||''} description={confirmState?.description||''} confirmLabel={confirmState?.confirmLabel} getErrorMessage={confirmState?.getErrorMessage} onConfirm={confirmState?.action||(()=>{})} onClose={()=>setConfirmState(null)}/>}
    <NoticeDialog open={Boolean(notice)} title={notice?.title||''} description={notice?.description||''} onClose={()=>setNotice(null)}/>
  </div>
}

export default App
